INSERT INTO artists VALUES(1,'The Beatles','the-beatles','the-beatles','GB',1960,'["1960s","60s","beat","british","british invasion","classic rock","europe","film soundtrack","liverpool","mainstream rock","merseybeat","pop","pop rock","psychedelia","psychedelic pop","psychedelic rock","rock","rock and roll"]','[{"name":"Stuart Sutcliffe","mbid":"49a51491-650e-44b3-8085-2f07ac2986dd","instruments":"bass guitar","beginDate":"1960-01","endDate":"1961","ended":true},{"name":"Tommy Moore","mbid":"f7d30d7d-9976-4d31-9907-19f3c30a206d","instruments":"drums (drum set)","beginDate":"1960-05","endDate":"1960-06","ended":true},{"name":"Norman Chapman","mbid":"6a0e143b-61bb-414f-99c8-96681be286a1","instruments":"drums (drum set)","beginDate":"1960-06","endDate":"1960-06","ended":true},{"name":"Pete Best","mbid":"0d4ab0f9-bbda-4ab1-ae2c-f772ffcfbea9","instruments":"drums (drum set)","beginDate":"1960-08-12","endDate":"1962-08-16","ended":true},{"name":"Chas Newby","mbid":"2629082c-19b4-42ae-b2e1-d6025ead67a0","instruments":"bass guitar","beginDate":"1960-12","endDate":"1961-01","ended":true},{"name":"John Lennon","mbid":"4d5447d7-c61c-4120-ba1b-d7f471d385b9","instruments":"guitar, lead vocals, original","beginDate":"1960","endDate":"1969-09","ended":true},{"name":"George Harrison","mbid":"42a8f507-8412-4611-854f-926571049fa0","instruments":"guitar, lead vocals, original","beginDate":"1960","endDate":"1970-04-10","ended":true},{"name":"Paul McCartney","mbid":"ba550d0e-adac-4864-b88b-407cab5e76af","instruments":"bass guitar, lead vocals, original","beginDate":"1960","endDate":"1970-04-10","ended":true},{"name":"Ringo Starr","mbid":"300c4c73-33ac-4255-9d57-4e32627f5e13","instruments":"drums (drum set)","beginDate":"1962-08","endDate":"1970-04-10","ended":true}]',replace('The Beatles were an English rock band formed in Liverpool, Lancashire in 1960. With the line-up comprising John Lennon, Paul McCartney,  George Harrison, and Ringo Starr, they are regarded as the most popular and influential band of all time. The group was integral to the development of 1960s counterculture and popular music''s recognition as an art form. Rooted in skiffle, beat and 1950s rock and roll, their sound incorporated elements of classical music and traditional pop in innovative ways; the band later explored music styles ranging from ballads and Indian music to psychedelia and hard rock. As pioneers in recording, songwriting and artistic presentation, the group revolutionized many aspects of the music industry and were often publicized as leaders of the era''s youth and socio-cultural movements. \n\nLed by primary songwriters Lennon and McCartney, the Beatles built their reputation playing clubs in Liverpool and Hamburg over three years from 1960, initially with Stuart Sutcliffe playing bass. The core trio of Lennon, McCartney and Harrison, together since 1958, went through a succession of drummers, eventually settling with Pete Best in 1960, who played with them for two years before being replaced with then Rory Storm & The Hurricanes drummer Ringo Starr in 1962. Manager Brian Epstein molded them into a professional act and producer George Martin guided and developed their recordings, greatly expanding their domestic success after their first hit, "Love Me Do", in late 1962. As their popularity grew into the intense fan frenzy dubbed "Beatlemania", the band acquired the nickname "the Fab Four", with Epstein, Martin and other members of the band''s entourage sometimes given the informal title of "fifth Beatle".\n\nBy early 1964, the Beatles were international stars, leading the "British Invasion" of the United States pop market and breaking numerous sales records. They soon made their film debut with A Hard Day''s Night (1964). From 1965 onwards, they produced increasingly innovative recordings, including the albums Rubber Soul (1965), Revolver (1966) and Sgt. Pepper''s Lonely Hearts Club Band (1967), and enjoyed further commercial success with The Beatles (also known as "the White Album", 1968) and Abbey Road (1969). In 1968, they founded Apple Corps, a multi-armed multimedia corporation that continues to oversee projects related to the band''s legacy. After the group''s break-up in 1970, all four members enjoyed success as solo artists. Lennon was shot and killed in December 1980, and Harrison died of lung cancer in November 2001. McCartney and Starr remain musically active.\n\nThe Beatles are the best-selling music act of all time, with estimated sales of 600 million units worldwide. They hold the record for most number-one albums on the UK Albums Chart, most number-one hits on the Billboard Hot 100 chart, and most singles sold in the UK. The group was inducted into the Rock and Roll Hall of Fame in 1988, and all four main members were inducted individually between 1994 and 2015. In 2008, the group topped Billboard''s list of the all-time most successful artists on the Billboard Hot 100. The band received seven Grammy Awards, four Brit Awards, an Academy Award (for Best Original Song Score for the 1970 film Let It Be) and fifteen Ivor Novello Awards. Time magazine named them among the 20th century''s 100 most important people.\n\nFormer Rolling Stone associate editor Robert Greenfield compared the Beatles to Picasso, as "artists who broke through the constraints of their time period to come up with something that was unique and original "... In the form of popular music, no one will ever be more revolutionary, more creative and more distinctive ..." The British poet Philip Larkin described their work as "an enchanting and intoxicating hybrid of African-American rock-and-roll with their own adolescent romanticism", and "the first advance in popular music since the War".\n\nThey not only sparked the British Invasion of the US, they became a globally influential phenomenon as well. From the 1920s, the US had dominated popular entertainment culture throughout much of the world, via Hollywood films, jazz, the music of Broadway and Tin Pan Alley and, later, the rock and roll that first emerged in Memphis, Tennessee. The Beatles are regarded as British cultural icons, with young adults from abroad naming the band among a group of people that they most associated with UK culture.\n\nTheir musical innovations and commercial success inspired musicians worldwide. Many artists have acknowledged the Beatles'' influence and enjoyed chart success with covers of their songs. On radio, their arrival marked the beginning of a new era; in 1968 the programme director of New York''s WABC radio station forbade his DJs from playing any "pre-Beatles" music, marking the defining line of what would be considered oldies on American radio. They helped to redefine the album as something more than just a few hits padded out with "filler", and they were primary innovators of the modern music video. The Shea Stadium show with which they opened their 1965 North American tour attracted an estimated 55,600 people, then the largest audience in concert history; Spitz describes the event as a "major breakthrough ... a giant step toward reshaping the concert business". Emulation of their clothing and especially their hairstyles, which became a mark of rebellion, had a global impact on fashion.\n\nAccording to Gould, the Beatles changed the way people listened to popular music and experienced its role in their lives. From what began as the Beatlemania fad, the group''s popularity grew into what was seen as an embodiment of socio-cultural movements of the decade. As icons of the 1960s counterculture, Gould continues, they became a catalyst for bohemianism and activism in various social and political arenas, fuelling movements such as women''s liberation, gay liberation and environmentalism. According to Peter Lavezzoli, after the "more popular than Jesus" controversy in 1966, the Beatles felt considerable pressure to say the right things and "began a concerted effort to spread a message of wisdom and higher consciousness".\n\n\nOther commentators such as Mikal Gilmore and Todd Leopold have traced the inception of their socio-cultural impact earlier, interpreting even the Beatlemania period, particularly on their first visit to the US, as a key moment in the development of generational awareness. Referring to their appearance on the Ed Sullivan Show Leopold states: "In many ways, the Sullivan appearance marked the beginning of a cultural revolution ... The Beatles were like aliens dropped into the United States of 1964.\n\nIn 1965, Queen Elizabeth II appointed Lennon, McCartney, Harrison and Starr Members of the Order of the British Empire (MBE). The Beatles won the 1971 Academy Award for Best Original Song Score for the film Let It Be (1970). The recipients of seven Grammy Awards and fifteen Ivor Novello Awards, the Beatles have six Diamond albums, as well as 20 Multi-Platinum albums, 16 Platinum albums and six Gold albums in the US. In the UK, the Beatles have four Multi-Platinum albums, four Platinum albums, eight Gold albums and one Silver album. They were inducted into the Rock and Roll Hall of Fame in 1988.\n\nThe best-selling band in history, the Beatles have sold more than 800 million physical and digital albums as of 2013. They have had more number-one albums on the UK charts, fifteen, and sold more singles in the UK, 21.9 million, than any other act. In 2004, Rolling Stone ranked the Beatles as the most significant and influential rock music artists of the last 50 years. They ranked number one on Billboard magazine''s list of the all-time most successful Hot 100 artists, released in 2008 to celebrate the US singles chart''s 50th anniversary. As of 2017, they hold the record for most number-one hits on the Billboard Hot 100, with twenty. The Recording Industry Association of America certifies that the Beatles have sold 178 million units in the US, more than any other artist. They were collectively included in Time magazine''s compilation of the 20th century''s 100 most influential people. In 2014, they received the Grammy Lifetime Achievement Award.\n\nThere are two holidays celebrated for the Beatles: Global Beatles Day on 25 June each year. On that date in 1967, the band performed "All You Need Is Love" on television. In 2001, UNESCO created World Beatles Day on 16 January each year. This date has direct relation to the opening of The Cavern Club in 1957.\n\nFive asteroids, 4147 Lennon, 4148 McCartney, 4149 Harrison, 4150 Starr and 8749 Beatles are named after the Beatles. <a href="https://www.last.fm/music/The+Beatles">Read more on Last.fm</a>. User-contributed text is available under the Creative Commons By-SA License; additional terms may apply.','\n',char(10)),'{"profile":"https://i.scdn.co/image/ab6761610000e5ebe9348cc01ff5d55971b22433","banner":"https://i.scdn.co/image/ab67616100005174e9348cc01ff5d55971b22433","main":"https://i.discogs.com/txwfZBYDvdK2_f0o4rsQXNbsGS4IQS9U0LmGybWMLh8/rs:fit/g:sm/q:90/h:600/w:600/czM6Ly9kaXNjb2dz/LWRhdGFiYXNlLWlt/YWdlcy9BLTgyNzMw/LTE0MTk3MTQ5ODgt/OTY3NS5qcGVn.jpeg"}','b10bbbfc-cf9e-42e0-be17-e2c3e1d2600d','Q1299','[a82730]','3WrFJ7ztbogyGnTHbHJFl2','https://www.last.fm/music/The+Beatles','0000000121707484','{"discogsArtistId":"[a82730]","spotifyArtistId":"3WrFJ7ztbogyGnTHbHJFl2","lastfmUrl":"https://www.last.fm/music/The+Beatles","geniusArtistId":"The-beatles","twitter":"thebeatles","facebook":"thebeatles","instagram":"thebeatles","wikidataEntityId":"Q1299","youtubeChannelId":"UC2XdaAVUannpujzv32jcouQ"}','thebeatles','thebeatles','thebeatles','UC2XdaAVUannpujzv32jcouQ',194,1753566010,1753567631,'The Beatles were an English rock band formed in Liverpool, Lancashire in 1960. With the line-up comprising John Lennon, Paul McCartney,  George Harrison, and Ringo Starr, they are regarded as the most popular and influential band of all time. The group was integral to the development of 1960s counterculture and popular music''s recognition as an art form. Rooted in skiffle, beat and 1950s rock and roll, their sound incorporated elements of classical <a href="https://www.last.fm/music/The+Beatles">Read more on Last.fm</a>','["1960s","60s","beat","british","british invasion","classic rock","europe","film soundtrack","liverpool","mainstream rock","merseybeat","pop","pop rock","psychedelia","psychedelic pop","psychedelic rock","rock","rock and roll"]',86,5829268,884787111,'["lastfm","spotify","discogs"]',1753567631);
INSERT INTO artists VALUES(2,'Pink Floyd','pink-floyd','pink-floyd','GB',1965,'["art rock","classic rock","progressive","progressive rock","psychedelic","psychedelic pop","psychedelic rock","rock","rock opera","space rock"]','[{"name":"Syd Barrett","mbid":"12327d75-47d5-45d9-84c2-3760b9210c17","instruments":"guitar, lead vocals","beginDate":"1965","endDate":"1968-04","ended":true},{"name":"Richard Wright","mbid":"6f7e36da-79d8-4219-990d-8e9224d04ebc","instruments":"keyboard, lead vocals","beginDate":"1965","endDate":"1981","ended":true},{"name":"Roger Waters","mbid":"0f50beab-d77d-4f0f-ac26-0b87d3e9b11b","instruments":"bass guitar, lead vocals","beginDate":"1965","endDate":"1985","ended":true},{"name":"Nick Mason","mbid":"d6c37074-0155-46a3-8af2-338a4f625afc","instruments":"drums (drum set), percussion","beginDate":"1965","endDate":null,"ended":false},{"name":"David Gilmour","mbid":"1dce970e-34bc-48b2-ab51-48d87544a4c2","instruments":"guitar, lead vocals, slide guitar","beginDate":"1968-02-18","endDate":null,"ended":false},{"name":"Richard Wright","mbid":"6f7e36da-79d8-4219-990d-8e9224d04ebc","instruments":"keyboard, lead vocals","beginDate":"1987","endDate":"2008-09-15","ended":true}]',replace('Pink Floyd was an English progressive and art rock band formed in London in 1965. Gaining an early following as one of the first British psychedelic groups, they were distinguished by their extended compositions, sonic experimentation, philosophical lyrics and elaborate live shows. They became a leading band of the progressive rock genre, cited by some as the greatest progressive rock band of all time.\n\nPink Floyd were founded in 1965 by Syd Barrett (guitar, lead vocals), Nick Mason (drums), Roger Waters (bass guitar, vocals), and Richard Wright (keyboards, vocals). Under Barrett''s leadership, they released two charting singles and the successful debut album The Piper at the Gates of Dawn (1967). Guitarist and vocalist David Gilmour joined in December 1967; Barrett left in April 1968 due to deteriorating mental health. Waters became the primary lyricist and thematic leader, devising the concepts behind the band''s peak success with the albums The Dark Side of the Moon (1973), Wish You Were Here (1975), Animals (1977) and The Wall (1979). The musical film based on The Wall, Pink Floyd – The Wall (1982), won two BAFTA Awards. Pink Floyd also composed several film scores.\n\nFollowing personal tensions, Wright was pushed out of Pink Floyd in 1979, followed by Waters decision to leave in 1985. Gilmour and Mason continued as Pink Floyd, rejoined later by Wright. They produced two more albums—A Momentary Lapse of Reason (1987) and The Division Bell (1994)—and toured in support of both before entering a long hiatus. In 2005, all but Barrett reunited for a one-off performance at the global awareness event Live 8. Barrett died in 2006, and Wright in 2008. The last Pink Floyd studio album, The Endless River (2014), was created using unreleased material from the Division Bell recording sessions, along with new recordings. In 2022, Gilmour and Mason released the most recent Pink Floyd recording, the song "Hey, Hey, Rise Up!" in protest of the Russian invasion of Ukraine.  As of 2024, the band is back on hiatus, with Gilmour stating his willingness to reconvene under the right circumstances.\n\nBy 2013, Pink Floyd had sold more than 250 million records worldwide, making them one of the best-selling music artists of all time. The Dark Side of the Moon and The Wall were inducted into the Grammy Hall of Fame, and these albums and Wish You Were Here are among the best-selling albums of all time. Four Pink Floyd albums topped the US Billboard 200, and five topped the UK Album Chart. Pink Floyd''s hit singles include "See Emily Play" (1967), "Money" (1973), "Another Brick in the Wall, Part 2" (1979), "Not Now John" (1983), "On the Turning Away" (1987) and "High Hopes" (1994). They were inducted into the US Rock and Roll Hall of Fame in 1996 and the UK Music Hall of Fame in 2005. In 2008, Pink Floyd were awarded the Polar Music Prize in Sweden for their contribution to modern music.\n\nFull Wikipedia article: https://en.wikipedia.org/wiki/Pink_Floyd\n\nStudio albums\nThe Piper at the Gates of Dawn (1967)\nA Saucerful of Secrets (1968)\nMore (1969)\nUmmagumma (1969)\nAtom Heart Mother (1970)\nMeddle (1971)\nObscured by Clouds (1972)\nThe Dark Side of the Moon (1973)\nWish You Were Here (1975)\nAnimals (1977)\nThe Wall (1979)\nThe Final Cut (1983)\nA Momentary Lapse of Reason (1987)\nThe Division Bell (1994)\nThe Endless River (2014) <a href="https://www.last.fm/music/Pink+Floyd">Read more on Last.fm</a>. User-contributed text is available under the Creative Commons By-SA License; additional terms may apply.','\n',char(10)),'{"profile":"https://i.scdn.co/image/e69f71e2be4b67b82af90fb8e9d805715e0684fa","banner":"https://i.scdn.co/image/d011c95081cd9a329e506abd7ded47535d524a07","main":"https://i.discogs.com/L3xODvccXCrOv8yQ717EIfcw52brkl4GlTv6rkGVAXo/rs:fit/g:sm/q:90/h:397/w:600/czM6Ly9kaXNjb2dz/LWRhdGFiYXNlLWlt/YWdlcy9BLTQ1NDY3/LTE0MDU1OTMzMDIt/ODYzMy5qcGVn.jpeg"}','83d91898-7763-47d7-b03b-b92132375c47','Q2306','[a45467]','0k17h0D3J5VfsdmQ1iZtE9','https://www.last.fm/music/Pink+Floyd','0000000109397559','{"discogsArtistId":"[a45467]","spotifyArtistId":"0k17h0D3J5VfsdmQ1iZtE9","lastfmUrl":"https://www.last.fm/music/Pink+Floyd","geniusArtistId":"Pink-floyd","twitter":"PinkFloyd","facebook":"pinkfloyd","instagram":"pinkfloyd","wikidataEntityId":"Q2306","youtubeChannelId":"UCO6LS_5W7vqG9mALDNzSFug"}','PinkFloyd','pinkfloyd','pinkfloyd','UCO6LS_5W7vqG9mALDNzSFug',191,1753566010,1753567632,replace('Pink Floyd was an English progressive and art rock band formed in London in 1965. Gaining an early following as one of the first British psychedelic groups, they were distinguished by their extended compositions, sonic experimentation, philosophical lyrics and elaborate live shows. They became a leading band of the progressive rock genre, cited by some as the greatest progressive rock band of all time.\n\nPink Floyd were founded in 1965 by Syd Barrett (guitar <a href="https://www.last.fm/music/Pink+Floyd">Read more on Last.fm</a>','\n',char(10)),'["art rock","classic rock","progressive","progressive rock","psychedelic","psychedelic pop","psychedelic rock","rock","rock opera","space rock"]',83,4875780,504529670,'["lastfm","spotify","discogs"]',1753567632);
INSERT INTO artists VALUES(3,'David Bowie','david-bowie','david-bowie','GB',1947,'["actors","alternative rock","arrangers","art pop","art rock","british","classic rock","composers","glam rock","glam rock music","glam rock musicians","new wave","pop","pop rock","rock","rock music","rock musicians","singers","sound recording executives and producers","uk"]','[]',replace('David Robert Jones (8 January 1947 – 10 January 2016), known professionally as David Bowie, was an English singer-songwriter and actor. A leading figure in the music industry, he is regarded as one of the most influential musicians of the 20th century. Bowie was acclaimed by critics and musicians, particularly for his innovative work during the 1970s. His career was marked by reinvention and visual presentation, and his music and stagecraft had a significant impact on popular music.\n\nBowie developed an interest in music from an early age. He studied art, music and design before embarking on a professional career as a musician in 1963. "Space Oddity", released in 1969, was his first top-five entry on the UK Singles Chart. After a period of experimentation, he re-emerged in 1972 during the glam rock era with his flamboyant and androgynous alter ego Ziggy Stardust. The character was spearheaded by the success of Bowie''s single "Starman" and album The Rise and Fall of Ziggy Stardust and the Spiders from Mars, which won him widespread popularity. In 1975, Bowie''s style shifted towards a sound he characterised as "plastic soul", initially alienating many of his UK fans but garnering him his first major US crossover success with the number-one single "Fame" and the album Young Americans. In 1976, Bowie starred in the cult film The Man Who Fell to Earth and released Station to Station. In 1977, he again changed direction with the electronic-inflected album Low, the first of three collaborations with Brian Eno that came to be known as the "Berlin Trilogy". "Heroes" (1977) and Lodger (1979) followed; each album reached the UK top five and received lasting critical praise.\n\nAfter uneven commercial success in the late 1970s, Bowie had three number-one hits: the 1980 single "Ashes to Ashes", its album Scary Monsters (and Super Creeps), and "Under Pressure" (a 1981 collaboration with Queen). He achieved massive commercial success in the 1980s starting with Let''s Dance (1983). Between 1988 and 1992, he fronted the hard rock band Tin Machine before resuming his solo career in 1993. Throughout the 1990s and 2000s, Bowie continued to experiment with musical styles, including industrial and jungle. He also continued acting; his roles included Major Jack Celliers in Merry Christmas, Mr. Lawrence (1983), Jareth the Goblin King in Labyrinth (1986), Pontius Pilate in The Last Temptation of Christ (1988), and Nikola Tesla in The Prestige (2006), among other film and television appearances and cameos. He stopped touring after 2004 and his last live performance was at a charity event in 2006. In 2013, Bowie returned from a decade-long recording hiatus with The Next Day. He remained musically active until his death from liver cancer at his home in New York City. He died two days after both his 69th birthday and the release of his final album, Blackstar (2016).\n\nDuring his lifetime, his record sales, estimated at over 100 million records worldwide, made him one of the best-selling musicians of all time. In the UK, he was awarded ten platinum, eleven gold and eight silver album certifications, and released 11 number-one albums. In the US, he received five platinum and nine gold certifications. He was inducted into the Rock and Roll Hall of Fame in 1996. Rolling Stone ranked him among the greatest artists in history. As of 2022, Bowie was the best-selling vinyl artist of the 21st century.\n\nFull Wikipedia article: https://en.wikipedia.org/wiki/David_Bowie\n\nStudio albums\nDavid Bowie (1967)\nDavid Bowie/Space Oddity (1969)\nThe Man Who Sold the World (1970)\nHunky Dory (1971)\nThe Rise and Fall of Ziggy Stardust and the Spiders from Mars (1972)\nAladdin Sane (1973)\nPin Ups (1973)\nDiamond Dogs (1974)\nYoung Americans (1975)\nStation to Station (1976)\nLow (1977)\n"Heroes" (1977)\nLodger (1979)\nScary Monsters (and Super Creeps) (1980)\nLet''s Dance (1983)\nTonight (1984)\nNever Let Me Down (1987)\nBlack Tie White Noise (1993)\nThe Buddha of Suburbia (1993)\nOutside (1995)\nEarthling (1997)\nHours (1999)\nHeathen (2002)\nReality (2003)\nThe Next Day (2013)\nBlackstar (2016) <a href="https://www.last.fm/music/David+Bowie">Read more on Last.fm</a>. User-contributed text is available under the Creative Commons By-SA License; additional terms may apply.','\n',char(10)),'{"profile":"https://i.scdn.co/image/ab6761610000e5ebb78f77c5583ae99472dd4a49","banner":"https://i.scdn.co/image/ab67616100005174b78f77c5583ae99472dd4a49","main":"https://i.discogs.com/Nc1FSm4J27mP2ZdvaR9uluSd7T8Vhn6uf5jw2SHdI3I/rs:fit/g:sm/q:90/h:591/w:598/czM6Ly9kaXNjb2dz/LWRhdGFiYXNlLWlt/YWdlcy9BLTEwMjYz/LTEzNDA4NzIyMTMt/OTc4MC5qcGVn.jpeg"}','5441c29d-3602-4898-b1a1-b77fa23b8e50','Q5383','[a10263]','0oSGxfWSnnOXhD2fKuz2Gy','https://www.last.fm/music/David+Bowie','0000000114448576','{"discogsArtistId":"[a10263]","spotifyArtistId":"0oSGxfWSnnOXhD2fKuz2Gy","lastfmUrl":"https://www.last.fm/music/David+Bowie","geniusArtistId":"David-bowie","twitter":"DavidBowieReal","instagram":"davidbowie","facebook":"davidbowie","wikidataEntityId":"Q5383","youtubeChannelId":"UCvY1eVE6lTebXsdFbbXUtkQ"}','DavidBowieReal','davidbowie','davidbowie','UCvY1eVE6lTebXsdFbbXUtkQ',181,1753566010,1753567633,'David Robert Jones (8 January 1947 – 10 January 2016), known professionally as David Bowie, was an English singer-songwriter and actor. A leading figure in the music industry, he is regarded as one of the most influential musicians of the 20th century. Bowie was acclaimed by critics and musicians, particularly for his innovative work during the 1970s. His career was marked by reinvention and visual presentation, and his music and stagecraft had a significant impact on popular music. <a href="https://www.last.fm/music/David+Bowie">Read more on Last.fm</a>','["actors","alternative rock","arrangers","art pop","art rock","british","classic rock","composers","glam rock","glam rock music","glam rock musicians","new wave","pop","pop rock","rock","rock music","rock musicians","singers","sound recording executives and producers","uk"]',80,5001572,340409666,'["lastfm","spotify","discogs"]',1753567633);
